{
  "book_name": "SOMEENGLISH",
  "book_long_title": "মহানদীর তীরে: পরীক্ষাগ্রন্থের রহস্য ও গৌড়ের অগ্নিসাক্ষী",
  "generic": "Historical Epic / Nationalist Literature",
  "era": "590AD-625AD",
  "language": "Bengali",
  "target_audience": "general public, history enthusiasts, students",
  "chapter_count": 2,
  "created_at": "2026-04-22",
  "user_name": "pijush",
  "book_summary": "৫৯০-৬২৫ খ্রিষ্টাব্দের গৌড় রাজ্যের পটভূমিতে এক রহস্যময় পাণ্ডুলিপি 'পরীক্ষাগ্রন্থ'কে কেন্দ্র করে রাজনৈতিক ষড়যন্ত্র, আত্মত্যাগ ও সত্যের সন্ধানের মহাকাব্যিক উপন্যাস।",
  "chapters": [
    {
      "chapter_index": 1,
      "name": "Chapter 1",
      "chapter_title": "অগ্নিগর্ভ সূচনা: পরীক্ষাগ্রন্থের আবির্ভাব",
      "chapter_summary": "৫৯০ খ্রিষ্টাব্দের গৌড় রাজ্যে রাজকীয় গ্রন্থাগারের তরুণ অধ্যক্ষ ধর্মপাল বর্মণ এক রাতে ধ্বংসপ্রাপ্ত মন্দিরের গর্ভে একটি রহস্যময় পান্ডুলিপি আবিষ্কার করেন, যার নাম 'পরীক্ষাগ্রন্থ'। এই গ্রন্থে নিহিত আছে গৌড়ের সিংহাসনের বৈধতা, প্রাচীন রক্তপাতের ইতিহাস এবং এক গুপ্ত শক্তির সন্ধান, যা রাজা শশাঙ্কের শত্রুরা দখল করতে মরিয়া। রাজকুমারী ইলা ধর্মপালকে সতর্ক করেন যে মহামন্ত্রী কেশব সেনের চোখ এই পান্ডুলিপির দিকে, এবং রাজদরবারে বিশ্বাসের সংকট ঘনীভূত হয়। ধর্মপাল গ্রন্থের প্রথম পৃষ্ঠা পাঠ করে বুঝতে পারেন এটি কেবল ইতিহাস নয়, বরং রাজ্যের নৈতিক ভিত্তি পরীক্ষা করার এক দার্শনিক দর্পণ, যা তাকে সত্য ও কর্তব্যের দ্বন্দ্বে ফেলে দেয়।",
      "reference_characters": [
        "ধর্মপাল বর্মণ",
        "রাজকুমারী ইলা",
        "মহামন্ত্রী কেশব সেন"
      ]
    },
    {
      "chapter_index": 2,
      "name": "Chapter 2",
      "chapter_title": "সত্যের অগ্নিপরীক্ষা: গৌড়ের চূড়ান্ত সংগ্রাম",
      "chapter_summary": "কেশব সেনের চক্রান্তে ধর্মপাল রাজদ্রোহের অভিযোগে বন্দি হন এবং রাজধানী অবরোধের মুখে দাঁড়ায়, অন্যদিকে রাজকুমারী ইলা প্রমাণ করেন যে 'পরীক্ষাগ্রন্থ' আসলে শশাঙ্কের পূর্বপুরুষদের আত্মসমর্পণের দলিল, যা প্রকাশ পেলে রাজবংশের পতন ঘটবে। ধর্মপাল অন্ধকূপ থেকে পালিয়ে গ্রন্থের শেষ অধ্যায় পাঠ করেন, যেখানে লেখা আছে প্রকৃত রাজশক্তি ভয় বা রক্তে নয়, ন্যায় ও জনকল্যাণে নিহিত। তিনি রাজসভায় গ্রন্থটি প্রকাশ করে রাজা শশাঙ্ককে অতীতের ভুল স্বীকারে বাধ্য করেন এবং কেশব সেনের ষড়যন্ত্র উন্মোচিত হয়। শেষে ধর্মপাল ও ইলা মিলে এক নতুন শপথ গ্রহণ করেন, যেখানে ইতিহাসের সত্যকে ধারণ করে গৌড়ের ভবিষ্যৎ নির্মাণের পথ খুলে যায়, আর পরীক্ষাগ্রন্থ চিরকালের জন্য জাতির নৈতিক সাক্ষী হয়ে থাকে।",
